import DatePicker from "react-multi-date-picker";
import opacity from "react-element-popper/animations/opacity";
import transition from "react-element-popper/animations/transition";

export default function MultiDatePicker({ selectedDates, setSelectedDates }) {
  return (
    <DatePicker
      format="DD/MM/YYYY" // ✅ Định dạng ngày
      portal={true} // ✅ Render lịch ra ngoài card nếu bị che
      range // ✅ Bật chế độ chọn khoảng ngày
      rangeHover// ✅ Bật chế độ chọn khoảng ngày 
      showOtherDays // ✅ Hiện tháng khác
      numberOfMonths={2} // ✅ số tháng cần hiện Hiện tháng khác
      minDate={new Date()} // ✅ Không cho chọn ngày trước hôm nay
      animations={[opacity(), transition({ from: 35, duration: 800 })]}
      value={selectedDates || new Date()} // ✅ Hiển thị danh sách ngày đã chọn
      onChange={(dates) => {
        if (dates.length > 2) return;
        setSelectedDates(dates);// ✅ Cập nhật danh sách ngày}
      }} 
      style={{
        width: "200px", // ✅ Giữ kích thước giống React-Select
        height: "40px",
        fontSize: "16px",
        borderRadius: "4px", // ✅ Bo góc đồng bộ với Select
        border: "1px solid #ccc", // ✅ Đảm bảo UI nhìn chuyên nghiệp
        padding: "10px",
      }}
    />
  );
}
