import React from "react";
import { useState } from "react";
import MultiDatePicker from "../components/DatePicker";
import LocationSelect from "../components/Select";
import RoomSelector from "../components/SelectBooking"
import {SearchSubmit} from "../service/apiService"
function Sreach() {
  const [selectedLocation, setSelectedLocation] = useState(null);
  const [selectedDate, setSelectedDate] = useState(null);
  const [customerValue, setCustomerValue] = useState(1);
  const [roomValue, setRoomValue] = useState(1);
  const handleSubmit = async (e) => {
    e.preventDefault();
    const result = await SearchSubmit(selectedLocation, selectedDate, customerValue, roomValue);
    console.log("Kết quả từ API:", result);
  };
const handleUpdate = (data) => {
  console.log("Dữ liệu nhận từ RoomSelector:", data);
  setCustomerValue(data.guests); // ✅ Cập nhật ngày
  setRoomValue(data.rooms); // ✅ Cập nhật số phòng
};
  return (
    <form onSubmit={handleSubmit}>
    <div class="sreach-form">
      <div class="card p-3">
        <div class="card-body row ">
          <div class="col-md-4 text-start">
            <label class="form-label" for="departureLocation">
              Điểm đi:
            </label>
            <LocationSelect
              selectedValue={selectedLocation}
              setSelectedValue={setSelectedLocation}
            />
          </div>
          <div class="col-md-4 text-start ">
            <div class="single-model-search ">
              <label class="form-label" for="departureDate">
                Ngày đi:
              </label>
              <MultiDatePicker
                selectedDates={selectedDate}
                setSelectedDates={setSelectedDate}
              />
            </div>
          </div>
          <div class="col-md-4 text-start">
            <div class="single-model-search">
              <label class="form-label" for="destinationLocation">
                Phòng:
              </label>
             <RoomSelector onUpdate={handleUpdate} />
            </div>
          </div>
         
        </div>
        <div class="text-center">
            <button class="btn btn-primary" type="submit">
              Tìm chuyến xe
            </button>
          </div>
      </div>

    </div>

    </form>
  );
}

export default Sreach;



