import { useQuery } from "@tanstack/react-query";
import axios from "axios";

export const fetchData = async () => {
    const response = await axios.get("http://localhost:8080/hotel/getLocation");
    return response.data;
  };

export const SearchSubmit = async(selectedLocation, selectedDate, customerValue, roomValue)=>{
  try {
    const response = await fetch("http://localhost:8080/hotel/getValueToForm", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ selectedLocation, selectedDate, customerValue, roomValue }),
    });

    if (!response.ok) throw new Error(`Lỗi: ${response.status}`);

    const result = await response.json();
    console.log("Phản hồi từ backend:", result);
    return result;
  } catch (error) {
    console.error("Lỗi khi gửi request:", error);
  }

}